	PureType<QUALIFIED> subject = *auto_ptr<PureType<QUALIFIED> >(subjectExpr->typeCheck(false));
	if(subject.type == TYPE_MATCHALL) {
		return new PureType<QUALIFIED>(subject);
	} else if(subject.type != TYPE_OPTIONAL) {
