int rs::httpserver::ResponseStream::Write(const Stream::byte* buffer, int offset, int count) {
    auto written = 0;

    while (written < count) {
        auto sentBytes = socket_->Send(buffer + written, count - written);
        if (sentBytes <= 0) {
            throw SocketWriteException();
        }

        written += sentBytes;
        position_ += sentBytes;
