class Solution {
  public:
    TreeNode *invertTree(TreeNode *root) {
        if (!root || (!root->left && !root->right)) {
            return root;
        }
        auto t = root->left;
        root->left = root->right;
        root->right = t;
        invertTree(root->left);
        invertTree(root->right);
        return root;
    }
};

