		case CTRL_LOGOFF_EVENT:
		case CTRL_SHUTDOWN_EVENT:
			std::cout << "The server is going DOWN!" << std::endl;
			stop = 1;
			// Same return as the default case.
		default:
			return FALSE;
	}
}

