{
	if (this->Stack.empty())
		return nullptr;
	else
		return this->Stack.top();
}

bool StageStack::IsEmpty()
{
	return this->Stack.empty();
}

void StageStack::Clear()
{
	while (!this->IsEmpty())
		this->Pop();
}

