    struct event_base* base = event_base_new();
    evpp::PipeEventWatcher ev(base, std::bind(&Handle, base));
    std::thread th(MyEventThread, base, &ev);
    ::usleep(1000 * 100);
    ev.Notify();
    th.join();
    event_base_free(base);
    H_TEST_ASSERT(g_event_handler_called == true);
}

